3694. pub open spec fn handle_update_request(installed_types: InstalledTypes, req: UpdateRequest, s: APIServerState) -> (APIServerState, UpdateResponse) {
3695.     if update_request_admission_check(installed_types, req, s) is Some {
3696.         // Update fails.
3697.         (s, UpdateResponse{res: Err(update_request_admission_check(installed_types, req, s)->0)})
3698.     } else {
3699.         let old_obj = s.resources[req.key()];
3700.         let updated_obj = updated_object(req, old_obj);
3701.         if updated_obj == old_obj {
3702.             // Update is a noop because there is nothing to update
3703.             // so the resource version counter does not increase here,
3704.             // and the resource version of this object remains the same.
3705.             (s, UpdateResponse{res: Ok(old_obj)})
3706.         } else {
3707.             // Update changes something in the object (either in spec or metadata), so we set it a newer resource version,
3708.             // which is the current rv counter.
3709.             let updated_obj_with_new_rv = updated_obj.with_resource_version(s.resource_version_counter);
3710.             if updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types) is Some {
3711.                 // Update fails.
3712.                 (s, UpdateResponse{res: Err(updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types)->0)})
3713.             } else {
3714.                 // Update succeeds.
3715.                 if updated_obj_with_new_rv.metadata.deletion_timestamp is None
3716.                     || (updated_obj_with_new_rv.metadata.finalizers is Some
3717.                         && updated_obj_with_new_rv.metadata.finalizers->0.len() > 0)
3718.                 {
3719.                     // The regular update case, where the object has no deletion timestamp set
3720.                     // or has at least one finalizer.
3721.                     (APIServerState {
3722.                         resources: s.resources.insert(req.key(), updated_obj_with_new_rv),
3723.                         resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3724.                         ..s
3725.                     }, UpdateResponse{res: Ok(updated_obj_with_new_rv)})
3726.                 } else {
3727.                     // The delete-during-update case, where the update removes the finalizers from
3728.                     // the object that has a deletion timestamp, so the object needs to be deleted now.
3729.                     //
3730.                     // NOTE: in the actual implementation, when handling an update request,
3731.                     // the API server first applies the update to the object in the key-value store,
3732.                     // then checks whether the object can be deleted.
3733.                     // If so, it continues to delete the object from the key-value store before replying
3734.                     // to the update request.
3735.                     // This means that there is a super short window where the object has been updated in the store
3736.                     // (with a deletion timestamp and without any finalizer), but has not been deleted yet.
3737.                     // This behavior, strictly speaking, makes the entire Update operation not atomic.
3738.                     // We choose to still model the Update operation as an atomic step for simplicity.
3739.                     // This design choice does not affect the correctness of the controller that issues Update
3740.                     // in a blocking manner because the controller will never observe this intermediate state between
3741.                     // the update and deletion.
3742.                     // More generally speaking, this modeling won't affect the correctness of any controller that
3743.                     // treats a terminating object without finalizers as a non-existing object --- a good practice
3744.                     // controllers should follow.
3745.                     //
3746.                     // NOTE: the API server should also check whether the deletion grace period in the metadata
3747.                     // is set to 0 before deleting the object in case of graceful deletion
3748.                     // (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/staging/src/k8s.io/apiserver/pkg/registry/generic/registry/store.go#L533).
3749.                     // Here we omit that condition because graceful deletion is not supported.
3750.                     (APIServerState {
3751.                         resources: s.resources.remove(updated_obj_with_new_rv.object_ref()),
3752.                         resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3753.                         ..s
3754.                     }, UpdateResponse{res: Ok(updated_obj_with_new_rv)})
3755.                 }
3756.             }
3757.         }
3758.     }
